std::vector<std::vector<std::string> > groupAnagrams(std::vector<std::string> words) {
    std::map<std::string, std::vector<std::string> > groups;
    for (std::size_t i = 0; i < words.size(); ++i) {
        std::string key = words[i];
        std::sort(key.begin(), key.end());
        groups[key].push_back(words[i]);
    }
    std::vector<std::vector<std::string> > out;
    for (std::map<std::string, std::vector<std::string> >::iterator it = groups.begin(); it != groups.end(); ++it) {
        std::vector<std::string> group = it->second;
        std::sort(group.begin(), group.end());
        out.push_back(group);
    }
    return out;
}
